param([Parameter(Mandatory=$true)][ValidateSet('MongoShell','Oracle','Developer','Tests','Evidence','Presentation','Backup','Restore','Diagnostic','Update','Docs')][string]$Mode)
$ErrorActionPreference='Stop'
$root=Split-Path $PSScriptRoot -Parent
$state=Join-Path $env:LOCALAPPDATA 'SIGMA-Aqua-v2'
$cred=Join-Path $state 'credentials.env'
$mongo='sigma_aqua_v2-mongo-1'; $oracle='sigma_aqua_v2-oracle-1'
function D { & docker @args; if($LASTEXITCODE -ne 0){throw "Docker fallo: $($args[0])"} }
function Login { if(!(Test-Path $cred)){throw 'Ejecute instalar primero'}; $v=ConvertFrom-StringData (Get-Content $cred -Raw); "SIGMA_AQUA_TEST/$($v.APP_PWD)@//localhost:1521/FREEPDB1" }
function Sql([string]$body){ $r=("WHENEVER SQLERROR EXIT FAILURE ROLLBACK`nWHENEVER OSERROR EXIT FAILURE`nSET DEFINE OFF`nSET SERVEROUTPUT ON`n$body`nEXIT SUCCESS`n") | & docker exec -i $oracle sqlplus -L -s (Login); if($LASTEXITCODE -ne 0 -or ($r -match 'SP2-\d+')){ $r | Out-Host; throw 'SQLPlus fallo' }; $r }
function Folder($kind){
    $base=[Environment]::GetFolderPath('MyDocuments')
    if([string]::IsNullOrWhiteSpace($base) -or !(Test-Path -LiteralPath $base -PathType Container)){ $base=$state }
    $f=Join-Path $base ('SIGMA-Aqua\'+$kind+'\'+(Get-Date -Format yyyyMMdd-HHmmss)+'-'+[guid]::NewGuid().ToString('N').Substring(0,8))
    try { [System.IO.Directory]::CreateDirectory($f) | Out-Null } catch { $f=Join-Path $state ('Resultados\'+$kind+'\'+[guid]::NewGuid().ToString('N')); [System.IO.Directory]::CreateDirectory($f) | Out-Null }
    if(!(Test-Path -LiteralPath $f -PathType Container)){throw "No se pudo crear carpeta: $f"}
    return $f
}
function Compass { & (Join-Path $root '02_MongoDB\ABRIR_MONGO_COMPASS.cmd'); if($LASTEXITCODE -ne 0){throw 'Compass no disponible'} }
function Docs { Start-Process explorer.exe (Join-Path $root '08_Documentacion') }
try { switch($Mode){
'MongoShell' { D exec -it $mongo mongosh sigma_aqua }
'Oracle' { D exec -it $oracle sqlplus -L (Login) }
'Developer' { $app=Get-StartApps | Where-Object {$_.Name -like '*SQL Developer*'} | Select-Object -First 1; if($app){Start-Process explorer.exe ('shell:AppsFolder\'+$app.AppID)}else{$exe=Read-Host 'Ruta a sqldeveloper.exe (vacio para cancelar)'; if(!$exe){return}; Start-Process -FilePath $exe}; Write-Host 'Host 127.0.0.1, puerto 1522, servicio FREEPDB1, usuario SIGMA_AQUA_TEST. Clave en credentials.env (privado).' }
'Tests' {
 $hour=Sql "SET HEADING OFF FEEDBACK OFF`nSELECT TO_CHAR(SYSTIMESTAMP AT TIME ZONE 'America/Santiago','HH24') FROM dual;"
 if(($hour -join '').Trim() -in '04','05'){throw 'Ventana de mantenimiento Chile; reintente despues de 06:00'}
 if((Read-Host 'Ejecutar pruebas Oracle sobre esquema de demostracion con rollback y Mongo en BD temporal? Escriba SI') -ne 'SI'){return}
 $f=Folder 'Pruebas'; $db='sigma_aqua_test_'+[guid]::NewGuid().ToString('N'); $tmp=Join-Path $env:TEMP $db; New-Item -ItemType Directory $tmp | Out-Null
 try { foreach($n in 'Insert.js','InsertMany.js','Pruebas.js','Read.js','Update.js','Delete.js'){ $src=Join-Path $root "SIGMA-Aqua\NoSQL\$n"; $dest=Join-Path $tmp $n; $code=Get-Content $src -Raw -Encoding UTF8; $code=$code.Replace("'sigma_aqua'",("'"+$db+"'")).Replace('"sigma_aqua"',('"'+$db+'"')); if($code -match "getSiblingDB\s*\(\s*['`"]sigma_aqua['`"]" -or !$code.Contains($db)){throw "Aislamiento no confirmado: $n"}; $code | Set-Content $dest -Encoding UTF8; D cp $dest "${mongo}:/tmp/$db-$n"; $r=@(D exec $mongo mongosh $db --quiet --file "/tmp/$db-$n"); $r | Tee-Object -FilePath (Join-Path $f ($n+'.txt')) | Out-Host; if($n -eq 'Pruebas.js' -and @($r -match '^\s*\[OK\]').Count -ne 4){throw 'Mongo: pruebas incompletas'} }
 } finally { if($db -match '^sigma_aqua_test_[0-9a-f]{32}$'){ D exec $mongo mongosh --quiet --eval "db.getSiblingDB('$db').dropDatabase()" | Out-Null; foreach($n in 'Insert.js','InsertMany.js','Pruebas.js','Read.js','Update.js','Delete.js'){ D exec $mongo rm -f "/tmp/$db-$n" | Out-Null } }; Remove-Item -LiteralPath $tmp -Recurse -Force }
 foreach($n in '03_Poblado_y_Consultas/test_monitoreo.sql','02_Triggers_y_Funciones/Test_Trigger.sql'){ $r=@(Sql (Get-Content (Join-Path "$root\SIGMA-Aqua\SQL" $n) -Raw -Encoding UTF8)); $r | Tee-Object -FilePath (Join-Path $f ((Split-Path $n -Leaf)+'.txt')) | Out-Host; $expected=if($n -like '*test_monitoreo*'){10}else{6}; if(@($r -match '^\s*\[OK\]').Count -ne $expected){throw 'Oracle: pruebas incompletas'} }; Write-Host "20 pruebas originales confirmadas en esta ejecucion. Evidencia: $f" -ForegroundColor Green
}
'Evidence' { $f=Folder 'Evidencias'; D exec $mongo mongosh --quiet --eval "print(EJSON.stringify(db.getSiblingDB('sigma_aqua').reportes_jaula.find().toArray(),null,2))" | Set-Content (Join-Path $f 'documentos.json') -Encoding UTF8; D exec $mongo mongosh --quiet --eval "print(EJSON.stringify(db.getSiblingDB('sigma_aqua').reportes_jaula.getIndexes(),null,2))" | Set-Content (Join-Path $f 'indices.json') -Encoding UTF8; $r=Sql "SET PAGESIZE 100 LINESIZE 200`nSELECT table_name FROM user_tables ORDER BY table_name;`nSELECT object_name,object_type,status FROM user_objects WHERE object_type IN ('PACKAGE','PACKAGE BODY','TRIGGER','VIEW');`nSELECT status,validated,COUNT(*) FROM user_constraints GROUP BY status,validated;`nSELECT * FROM V_ICA_CENTRO;"; $r | Set-Content (Join-Path $f 'oracle.txt') -Encoding UTF8; $files=Get-ChildItem $f -File; $html='<html><meta charset="utf-8"><title>SIGMA-Aqua</title><style>body{font:16px Arial;margin:40px;max-width:1100px}pre{background:#eee;padding:16px;overflow:auto}</style><h1>SIGMA-Aqua - Evidencias</h1><p>'+ (Get-Date)+'</p>'; foreach($file in $files){$html+='<h2>'+ $file.Name+'</h2><pre>'+[System.Net.WebUtility]::HtmlEncode((Get-Content $file.FullName -Raw))+'</pre>'}; $html+='</html>'; $out=Join-Path $f 'index.html'; $html | Set-Content $out -Encoding UTF8; Start-Process $out }
'Presentation' { & (Join-Path $PSScriptRoot 'Instalar.ps1') -Mode Start; if($LASTEXITCODE -ne 0){throw 'Inicio fallo'}; & powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $PSScriptRoot 'Verificar.ps1'); if($LASTEXITCODE -ne 0){throw 'Verificacion fallo'}; Compass; Start-Process cmd.exe -ArgumentList ('/k ""'+(Join-Path $root '03_Oracle\ABRIR_ORACLE.cmd')+'""'); Docs }
'Backup' { $f=Folder 'Respaldos'; $id='sigma_'+(Get-Date -Format yyyyMMddHHmmss); D exec $mongo mongodump --db sigma_aqua --archive=/tmp/$id.archive --gzip; D cp "${mongo}:/tmp/$id.archive" (Join-Path $f 'mongo.archive'); $dir=(Sql "SET HEADING OFF FEEDBACK OFF`nSELECT directory_path FROM all_directories WHERE directory_name='DATA_PUMP_DIR';") -join ''; if(!$dir.Trim()){throw 'DATA_PUMP_DIR no accesible; use administrador Oracle para configurar Data Pump'}; D exec $oracle expdp (Login) schemas=SIGMA_AQUA_TEST directory=DATA_PUMP_DIR dumpfile=$id.dmp logfile=$id.log; D cp "${oracle}:$($dir.Trim())/$id.dmp" (Join-Path $f 'oracle.dmp'); D cp "${oracle}:$($dir.Trim())/$id.log" (Join-Path $f 'oracle.log'); Write-Host "Respaldo: $f" }
'Restore' { $f=Read-Host 'Ruta de carpeta de respaldo'; if(!(Test-Path (Join-Path $f 'mongo.archive'))){throw 'Archivo mongo.archive ausente'}; $db='sigma_aqua_recuperado_'+(Get-Date -Format yyyyMMddHHmmss); if((Read-Host "Restaurar Mongo en nueva BD $db sin tocar original? SI") -ne 'SI'){return}; D cp (Join-Path $f 'mongo.archive') "${mongo}:/tmp/$db.archive"; D exec $mongo mongorestore --archive=/tmp/$db.archive --gzip --nsInclude='sigma_aqua.*' --nsFrom='sigma_aqua.*' --nsTo="$db.*"; Write-Host 'Oracle: restauracion requiere esquema de destino separado y permisos Data Pump. Consulte manual; no se sobrescribe automaticamente.' }
'Diagnostic' { D version; D ps -a --filter name=sigma_aqua_v2; D stats --no-stream $mongo $oracle; D logs --tail 30 $mongo; D logs --tail 30 $oracle; Get-NetTCPConnection -LocalPort 1522,27018 -ErrorAction SilentlyContinue | Format-Table }
'Update' { if(!(Get-Command git -ErrorAction SilentlyContinue)){throw 'Instale Git primero'}; $dest=Join-Path (Folder 'Actualizaciones') 'SIGMA-Aqua'; & git clone --branch main https://github.com/BlackCatVSC/SIGMA-Aqua.git $dest; if($LASTEXITCODE -ne 0){throw 'Git fallo'}; Write-Host "Copia nueva: $dest. Revise cambios antes de aplicar; no se modifica instalacion activa." }
'Docs' { Docs }
} } catch {Write-Host $_.Exception.Message -ForegroundColor Red; exit 1}
